pub async fn update_trade_status(
    auth: AuthUser,
    State(state): State<AppState>,
    Path(trade_id): Path<Uuid>,
    Json(req): Json<UpdateTradeStatusRequest>,
) -> Result<Json<TradeResponse>> {
    let db = state.require_db()?;
    let old_trade = crate::repo::trade::find_by_id(db, trade_id).await?;
    let old_status = old_trade.status;



    let is_buyer = auth.user_id == old_trade.buyer_id;
    let is_seller = auth.user_id == old_trade.seller_id;
    let is_vendor = old_trade.vendor_id == Some(auth.user_id);
    let is_admin = auth.role.has_admin_access();
    if !is_buyer && !is_seller && !is_vendor && !is_admin {
        return Err(AppError::forbidden(
            "you are not a participant in this trade",
        ));
    }


    if !old_status.can_transition_to(&req.status) {
        return Err(AppError::validation(invalid_transition_message(
            old_status, req.status,
        )));
    }









    if req.status == TradeStatus::Released {
        return Err(AppError::validation(
            "Use POST /trades/{id}/complete to release escrow — PATCH /status cannot move funds.",
        ));
    }








    if req.status == TradeStatus::Disputed {
        return Err(AppError::validation(
            "Use POST /trades/{id}/dispute to open a dispute — PATCH /status cannot freeze escrow or create a dispute record.",
        ));
    }


    if req.status == TradeStatus::Cancelled {
        return Err(AppError::validation(PATCH_STATUS_CANCEL_REFUSAL));
    }

    match req.status {
        TradeStatus::Paid => {
            if !is_buyer && !is_admin {
                return Err(AppError::forbidden(
                    "only the buyer can mark a trade as paid",
                ));
            }
            crate::services::trade_kyc::ensure_can_mark_paid(&old_trade)?;
        }
        TradeStatus::Released | TradeStatus::Completed => {



            let can_release = if old_trade.vendor_id.is_some() {
                is_seller || is_vendor || is_admin
            } else {
                is_seller || is_admin
            };
            if !can_release {
                return Err(AppError::forbidden(
                    "only the seller, vendor, or admin can release/complete a trade",
                ));
            }
        }
        TradeStatus::Disputed => {
            if !is_buyer && !is_seller && !is_vendor && !is_admin {
                return Err(AppError::forbidden("only trade participants can dispute"));
            }
        }
        TradeStatus::Resolved => {

            if !auth.role.has_moderator_access() {
                return Err(AppError::forbidden(
                    "only moderators or admins can resolve disputes",
                ));
            }
        }



        TradeStatus::Created | TradeStatus::EscrowFunded | TradeStatus::Cancelled => {}
    }

    let trade = crate::repo::trade::update_status(db, trade_id, req.status).await?;


    if let Err(e) = crate::repo::trade::add_event(
        db,
        trade_id,
        "status_changed",
        Some(auth.user_id),
        Some(serde_json::json!({
            "from": old_status.to_string(),
            "to": trade.status.to_string(),
        })),
    )
    .await
    {
        tracing::error!(trade_id = %trade_id, error = %e, "TF-010: failed to log status_changed event");
    }


    tracing::info!(
        trade_id = %trade_id,
        actor = %auth.user_id,
        from = %old_status,
        to = %trade.status,
        "MPR-006 trade state transition"
    );

    state
        .ws
        .broadcast(
            trade_id,
            crate::ws::WsMessage::TradeStatusChanged {
                trade_id: trade_id.to_string(),
                old_status: format!("{old_status}"),
                new_status: format!("{}", trade.status),
            },
        )
        .await;


    crate::socket_io::emit_trade_update(
        &state.io,
        trade_id,
        &old_status.to_string(),
        &trade.status.to_string(),
    )
    .await;

    let mut notify_ids: Vec<Uuid> = Vec::with_capacity(3);
    if auth.user_id != old_trade.buyer_id {
        notify_ids.push(old_trade.buyer_id);
    }
    if auth.user_id != old_trade.seller_id {
        notify_ids.push(old_trade.seller_id);
    }
    if let Some(vid) = old_trade.vendor_id {
        if auth.user_id != vid && vid != old_trade.seller_id {
            notify_ids.push(vid);
        }
    }
    for counterparty_id in &notify_ids {
        match crate::repo::notification::create(
            db,
            *counterparty_id,
            NotificationType::Trade,
            "Trade Status Updated",
            &format!(
                "Trade {} status changed: {} → {}",
                &trade_id.to_string()[..8],
                old_status,
                trade.status
            ),
            Some("trade"),
            Some(&trade_id.to_string()),
            Some(serde_json::json!({
                "tradeId": trade_id,
                "oldStatus": old_status.to_string(),
                "newStatus": trade.status.to_string(),
            })),
        )
        .await
        {
            Ok(notif) => {
                crate::services::notify::emit_to_user(&state.io, db, *counterparty_id, &notif)
                    .await;
            }
            Err(e) => {
                tracing::error!(
                    trade_id = %trade_id,
                    counterparty_id = %counterparty_id,
                    error = %e,
                    "failed to create status change notification"
                );
            }
        }
    }


    if trade.status == TradeStatus::Completed {
        for &participant_id in &[old_trade.buyer_id, old_trade.seller_id] {
            if let Err(e) = crate::repo::affiliate::activate_referral(db, participant_id).await {
                tracing::error!(
                    user_id = %participant_id,
                    trade_id = %trade_id,
                    error = %e,
                    "AFL-011: failed to activate referral on trade status update"
                );
            }
        }
        if let Some(vid) = old_trade.vendor_id {
            if let Err(e) = crate::repo::affiliate::activate_referral(db, vid).await {
                tracing::error!(
                    user_id = %vid,
                    trade_id = %trade_id,
                    error = %e,
                    "AFL-011: failed to activate referral for vendor on trade status update"
                );
            }
        }






        let escrow_lookup = crate::repo::escrow::find_by_trade(db, trade_id)
            .await
            .map(|escrow| (escrow.fee_amount, escrow.id));
        let basis = crate::services::affiliate_commission::CommissionBasis::from_escrow_lookup(
            escrow_lookup,
            || {
                crate::services::platform_fee::vendor_fee(
                    crypto_to_minor_units(old_trade.crypto_amount, old_trade.cryptocurrency),
                    state.fee_config.platform_fee_bps(),
                )
            },
        );
        settle_affiliate_commissions(&state, db, &old_trade, basis).await;
    }

    let merchant_tiers = merchant_tiers_for_trade(db, &state.config, &trade).await;
    Ok(Json(
        trade_to_response(db, &state.fee_config, &trade, &merchant_tiers).await,
    ))
}



