pub async fn link_onchain_escrow(
    auth: AuthUser,
    State(state): State<AppState>,
    Path(trade_id): Path<Uuid>,
    Json(req): Json<LinkOnChainEscrowRequest>,
) -> Result<Json<EscrowResponse>> {
    let db = state.require_db()?;
    let escrow = crate::repo::escrow::find_by_trade(db, trade_id).await?;

    let trade = crate::repo::trade::find_by_id(db, trade_id).await?;
    if auth.user_id != escrow.buyer_id
        && auth.user_id != escrow.seller_id
        && trade.vendor_id != Some(auth.user_id)
        && !auth.role.has_admin_access()
    {
        return Err(AppError::forbidden(
            "not authorized to link escrow for this trade",
        ));
    }



    if escrow.escrow_type != EscrowType::OnChain {
        crate::repo::escrow::update_escrow_type(db, escrow.id, EscrowType::OnChain).await?;
    }


    crate::repo::escrow::set_contract_address(db, escrow.id, &req.contract_address).await?;
    let updated =
        crate::repo::escrow::set_deposit(db, escrow.id, &req.contract_address, &req.tx_hash)
            .await?;

    tracing::info!(
        escrow_id = %updated.id,
        trade_id = %trade_id,
        contract_address = %req.contract_address,
        deposit_tx_hash = %req.tx_hash,
        network = ?req.network,
        old_escrow_type = ?escrow.escrow_type,
        new_escrow_type = "on_chain",
        "ESCROW_JOURNEY link_onchain: escrow linked with contract address and type updated to OnChain"
    );
    Ok(Json(escrow_to_response(&updated)))
}

pub fn validate_business_rules(&self) -> Result<()> {
    if self.min_amount > self.max_amount {
        return Err(AppError::validation("min_amount cannot exceed max_amount"));
    }
    if self.pricing_mode == PricingMode::Fixed && self.fixed_price.is_none() {
        return Err(AppError::validation(
            "fixed_price required when pricing_mode is fixed",
        ));
    }
    if self.pricing_mode == PricingMode::MarketPlusPremium && self.premium_percentage.is_none()
    {
        return Err(AppError::validation(
            "premium_percentage required when pricing_mode is market_plus_premium",
        ));
    }
    if self.payment_methods.is_empty() {
        return Err(AppError::validation("at least one payment method required"));
    }
    validate_offer_kyc_compatibility(
        self.require_id_doc.unwrap_or(false),
        self.require_bank_letter.unwrap_or(false),
        self.escrow_type,
        self.quote_currency
            .unwrap_or_else(|| Currency::from(self.fiat_currency)),
    )?;
    if let Some(ref title) = self.title {
        validate_title_no_banned_words(title)?;
    }
    let vis = self.visibility.unwrap_or_default();
    if vis == OfferVisibility::Direct && self.target_user_id.is_none() {
        return Err(AppError::validation(
            "target_user_id required for direct offers",
        ));
    }
    if vis != OfferVisibility::Direct && self.target_user_id.is_some() {
        return Err(AppError::validation(
            "target_user_id only allowed for direct offers",
        ));
    }
    Ok(())
}

fn validate_offer_kyc_compatibility(
    require_id_doc: bool,
    require_bank_letter: bool,
    escrow_type: EscrowType,
    quote_currency: Currency,
) -> Result<()> {
    if !require_id_doc && !require_bank_letter {
        return Ok(());
    }
    if quote_currency.is_crypto() {
        return Err(AppError::validation(
            "Offer KYC requirements are only available for fiat payment trades",
        ));
    }
    match escrow_type {
        EscrowType::Custodial | EscrowType::OfferEscrow | EscrowType::BtcWalletLock => Ok(()),
        EscrowType::OnChain => Err(AppError::validation(
            "Offer KYC requirements require an escrow-backed fiat trade",
        )),
    }
}

