pub async fn lock_balance_for_trade_on(
    conn: &mut sqlx::PgConnection,
    user_id: Uuid,
    offer_id: Uuid,
    cryptocurrency: Cryptocurrency,
    amount: i64,
) -> Result<WalletLock, sqlx::Error> {
    let updated = sqlx::query(
        "UPDATE wallets SET balance = balance - $1, locked_balance = locked_balance + $1, updated_at = now()
         WHERE user_id = $2 AND cryptocurrency = $3 AND balance >= $1
         RETURNING id",
    )
    .bind(amount)
    .bind(user_id)
    .bind(cryptocurrency)
    .fetch_optional(&mut *conn)
    .await?;
    let _row = updated.ok_or_else(|| sqlx::Error::RowNotFound)?;
    let lock = sqlx::query_as::<_, WalletLock>(
        "INSERT INTO wallet_locks (id, user_id, offer_id, cryptocurrency, amount, locked_at)
         VALUES (gen_random_uuid(), $1, $2, $3, $4, now())
         RETURNING *",
    )
    .bind(user_id)
    .bind(offer_id)
    .bind(cryptocurrency)
    .bind(amount)
    .fetch_one(&mut *conn)
    .await?;
    Ok(lock)
}

